'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const { gunzipSync } = require('node:zlib');
const repair = require('../scripts/lib/reader-repair');
const tables = require('../scripts/lib/reader-tables');
const { locateReaderDraftTables } = require('../scripts/lib/reader-draft-order');
// Compressed only to keep the two complete real drafts and sealed source texts
// in this independent test file. No prompt, image payload or credentials copied.
// Evidence: run e8fb670d-9d73-4a6e-92e0-abb7f7bee53d, MUSE 2d8c9661 and
// Noise 392544d6 request/response; full original hashes remain in each record.
// sourceTables preserves actual caption/matrix/row metadata, not a fabricated DOM.
// These original paid outputs remain rejected; the source-derived planning
// example below is explicitly not a paid reply or a publication qualification.
const paidCases = JSON.parse(gunzipSync(Buffer.from('', 'base64')));
const sha = text => crypto.createHash('sha256').update(text).digest('hex');
const at = (draft, pointer) => pointer.slice(1).split('/').reduce((node, part) => node[part], draft);
const issue = {code:'reader_result_table_missing', message:'读者文章主结果表覆盖不足：原论文明确提供定量结果'};
const context = row => repair.buildRepairContext(row.draft, row.issues, row.sourceText, row.sourceText);
const expected = {
    '2610.20310':['/sections/8/body','/tableBindings/0','/sections/9/body','/tableBindings/1','/sections/10/body','/tableBindings/2'],
    '2610.20181':['/sections/7/body','/tableBindings/0','/tableBindings/1']
};
test('真实MUSE/Noise的完整原稿和来源只规划原结果正文及同绑定，不选择donor', () => {
    for (const row of paidCases) {
        const before = repair.hashDraft(row);
        assert.equal(repair.hashDraft(row.draft), row.draftSha256, row.id);
        assert.equal(sha(row.sourceText), row.sourceSha256, row.id);
        assert.equal(sha(row.rawResponse), row.outputTextSha256, row.id);
        const ctx = context(row);
        assert.equal(ctx.atomicOperation, null, row.id);
        assert.deepEqual(ctx.targets.map(t => t.path), expected[row.id]);
        assert.equal(ctx.evidence, row.sourceText, '完整封存证据没有截断');
        for (const target of ctx.targets) {
            assert.deepEqual(target.value, at(row.draft,target.path));
            assert.equal(target.oldSha256,repair.hashDraft(target.value));
            assert.match(target.repairInstruction,/表数、表序及绑定序号/);
            assert.match(target.repairInstruction,/不得合并\/删表/);
        }
        for (const table of locateReaderDraftTables(row.draft).filter(t => ['result','ablation'].includes(row.draft.sections[t.sectionIndex].kind))) {
            assert.ok(ctx.targets.some(t => t.path === table.path));
            assert.ok(ctx.targets.some(t => t.path === '/tableBindings/'+table.bindingIndex));
        }
        assert.throws(() => tables.validateReaderResultTableCoverage(row.draft.sections,{tables:row.sourceTables}), /主结果表覆盖不足/);
        assert.equal(repair.hashDraft(row),before,'规划不改变原稿、原失败或预算');
    }
});
test('两份真实付费错误搬表仍被旧严格后置检查拒绝，新规划也不授权原donor', () => {
    for (const row of paidCases) {
        const patch=JSON.parse(row.rawResponse), before=repair.hashDraft(row);
        assert.throws(() => repair.applyReaderPatch(row.draft,patch,row.oldTargets.map(t=>t.path),
            {atomicOperation:row.oldOperation}), /atomic table-move postconditions/);
        const ctx=context(row);
        assert.throws(() => repair.applyReaderPatch(row.draft,patch,ctx.targets.map(t=>t.path),
            {atomicOperation:ctx.atomicOperation}), /unauthorized target|未授权目标/);
        assert.equal(repair.hashDraft(row),before);
    }
});
test('来源中实际结果值可在原位置通过结果覆盖，Noise的两张三格原表仍失败', () => {
    const noise=paidCases.find(x=>x.id==='2610.20181');
    const main=noise.sourceTables.find(t=>t.ordinal===1).matrix;
    const body=['| 方法 | Seed-TTS test-zh WER 0 dB | Seed-TTS test-zh WER -3 dB |',
        '|---|---|---|',...main.slice(3,5).map(row=>'| '+[row[0],row[1],row[2]].join(' | ')+' |')].join('\n');
    assert.equal(tables.validateReaderResultTableCoverage([{kind:'result',body}],{tables:noise.sourceTables}).numericResultTables,1);
    assert.throws(()=>tables.validateReaderResultTableCoverage(noise.draft.sections,{tables:noise.sourceTables}),/主结果表覆盖不足/);
});
function fixture(body,between='') {
    const sections=[{kind:'experiment_setup',heading:'原结果',body}];
    if(between)sections.push({kind:'experiment_setup',heading:'配置',body:between});
    sections.push({kind:'result',heading:'结果',body:'尚未呈现结果表。'});
    return {version:3,sections,conceptBridges:[],figurePlacements:[],formulaBindings:[],
        tableBindings:sections.flatMap(s=>require('../scripts/analysis-contract').extractMarkdownTables(s.body))
            .map((_t,index)=>({tableIndex:index+1,sourceType:'source_quotes',sourceTableOrdinal:null,
                cellBindings:[],sourceQuotes:['原文中的真实连续比较证据仍须由最终来源解析器核验。']}))};
}
function realResultBody() {
    const main=paidCases.find(x=>x.id==='2610.20181').sourceTables.find(t=>t.ordinal===1).matrix;
    return ['| Model | WER 0 dB | WER -3 dB |','|---|---|---|',
        ...main.slice(3,5).map(row=>'| '+[row[0],row[1],row[2]].join(' | ')+' |')].join('\n');
}
test('无既有结果表时仅保留不跨其他表、绑定原序号不变的原有搬表协议', () => {
    const d=fixture(realResultBody()), ctx=repair.buildRepairContext(d,[issue],'完整证据');
    assert.equal(ctx.atomicOperation.kind,'relocate_result_table_v1');
    assert.equal(ctx.atomicOperation.donorGlobalTableIndex,1);
    const replacements=ctx.targets.map(t=>({path:t.path,oldSha256:t.oldSha256,
        value:t.path==='/sections/0/body'?'原设置说明保留。':t.path==='/sections/1/body'?'结果解释。\n\n'+d.sections[0].body:t.value}));
    const next=repair.applyReaderPatch(d,{version:1,draftSha256:repair.hashDraft(d),replacements},
        ctx.targets.map(t=>t.path),{atomicOperation:ctx.atomicOperation});
    assert.equal(locateReaderDraftTables(next)[0].tableIndex,1);
    assert.deepEqual(next.tableBindings,d.tableBindings);
});
test('配置、数据、成本donor和会改其他表全局编号的搬表不生成请求范围', () => {
    const invalid=[
        '| 模型配置 | 参数量 | 推理实时率 |\n|---|---|---|\n| A | 336 | 0.26 |\n| B | 382 | 0.27 |',
        '| Dataset | Samples | Hours |\n|---|---|---|\n| A | 100 | 20 |\n| B | 200 | 30 |',
        '| 类别 | 训练集 | 验证集 | 测试集 |\n|---|---|---|---|\n| A | 100 | 20 | 30 |\n| B | 200 | 40 | 60 |',
        '| 配置 | A | B |\n|---|---|---|\n| 学习率 | 0.001 | 0.002 |\n| 批量大小 | 64 | 128 |'
    ];
    for(const body of invalid){
        const ctx=repair.buildRepairContext(fixture(body),[issue],'完整证据');
        assert.equal(ctx.atomicOperation,null);assert.deepEqual(ctx.targets,[]);
    }
    const cross=repair.buildRepairContext(fixture(realResultBody(),invalid[0]),[issue],'完整证据');
    assert.equal(cross.atomicOperation,null);assert.deepEqual(cross.targets,[]);
});
test('结果局部修复不猜不闭合绑定，也不扩大为整数组权限', () => {
    for(const row of paidCases){
        const draft=structuredClone(row.draft);draft.tableBindings[0].tableIndex=99;
        const ctx=repair.buildRepairContext(draft,[issue],row.sourceText,row.sourceText);
        assert.equal(ctx.atomicOperation,null);assert.deepEqual(ctx.targets,[]);
    }
});
